#!/bin/bash
set -e
APP_RES="$HOME/NOVA/app/src/main/res"
ICON_B64=""
for dir in mipmap-mdpi mipmap-hdpi mipmap-xhdpi mipmap-xxhdpi mipmap-xxxhdpi; do
    mkdir -p "$APP_RES/$dir"
    echo "$ICON_B64" | base64 -d > "$APP_RES/$dir/ic_launcher.png"
    echo "$ICON_B64" | base64 -d > "$APP_RES/$dir/ic_launcher_round.png"
done
echo "NOVA icon installed."
